// src/lib/formatters.ts
function formatDate(iso) {
  if (!iso) return "\u2014";
  const dateOnly = /^(\d{4})-(\d{2})-(\d{2})$/.exec(iso);
  const d2 = dateOnly ? new Date(Number(dateOnly[1]), Number(dateOnly[2]) - 1, Number(dateOnly[3])) : new Date(iso);
  if (Number.isNaN(d2.getTime())) return "\u2014";
  return d2.toLocaleDateString("en-US", { year: "numeric", month: "short", day: "numeric" });
}

